    def test_one_on_one_other_declined(self):
        """1:1 where the other person declined → alert."""
        event = _make_event(
            attendees=[
                _make_attendee("me@example.com", "accepted", is_self=True),
                _make_attendee("them@example.com", "declined"),
            ]
        )
        alerts = detect_declined_meetings([event], now=NOW)
        assert len(alerts) == 1
        assert alerts[0].all_others_declined is True
        assert alerts[0].declined_attendees == ["them@example.com"]
        assert alerts[0].total_attendees == 1

